function outer() {
  let name = "Alice";

  function inner() {
    console.log("Hello, " + name); // name আসে outer() থেকে
  }

  return inner;
}

const greet = outer(); // outer() রিটার্ন করে inner
greet(); // "Hello, Alice"

function secretHolder() {
  let secret = "1234";

  return {
    getSecret: function () {
      return secret;
    },
    setSecret: function (newSecret) {
      secret = newSecret;
    },
  };
}

const vault = secretHolder();
console.log(vault.getSecret()); // "1234"
vault.setSecret("5678");
console.log(vault.getSecret()); // "5678"

