class BankAccount:
    def __init__(self):
        self._balance = 0

    @property
    def balance(self):
        return self._balance

    @balance.setter
    def balance(self, value):
        if value < 0:
            raise ValueError("Balance cannot be negative.")
        self._balance = value

account = BankAccount()
account.balance = 500   # looks like a plain attribute, actually calls the setter
print(account.balance)  # 500 — looks like a plain attribute, actually calls the getter
# account.balance = -10 # ValueError — the setter blocks this

